def partial_derivs_vec(fct, delta):
    nx, ny, nz = fct.shape
    deriv_x = zeros((nx, ny, nz))
    deriv_y = zeros((nx, ny, nz))
    deriv_z = zeros((nx, ny, nz))

    # Compute interior points using central differences
    for i in range(1, nx-1):
        for j in range(1, ny-1):
            for k in range(1, nz-1):
                deriv_x[i, j, k] = (fct[i+1, j, k] - fct[i-1, j, k]) / (2 * delta)
                deriv_y[i, j, k] = (fct[i, j+1, k] - fct[i, j-1, k]) / (2 * delta)
                deriv_z[i, j, k] = (fct[i, j, k+1] - fct[i, j, k-1]) / (2 * delta)

    # Compute boundary points using one-sided differences
    # x-direction boundaries
    for j in range(1, ny-1):
        for k in range(1, nz-1):
            deriv_x[0, j, k] = (fct[1, j, k] - fct[0, j, k]) / delta
            deriv_x[-1, j, k] = (fct[-1, j, k] - fct[-2, j, k]) / delta

    for i in range(1, nx-1):
        for k in range(1, nz-1):
            deriv_x[i, 0, k] = (fct[i+1, 0, k] - fct[i, 0, k]) / delta
            deriv_x[i, -1, k] = (fct[i, -1, k] - fct[i, -2, k]) / delta

    for i in range(1, nx-1):
        for j in range(1, ny-1):
            deriv_x[i, j, 0] = (fct[i+1, j, 0] - fct[i, j, 0]) / delta
            deriv_x[i, j, -1] = (fct[i, j, -1] - fct[i, j, -2]) / delta

    # y-direction boundaries
    for i in range(1, nx-1):
        for k in range(1, nz-1):
            deriv_y[0, i, k] = (fct[1, 0, k] - fct[0, 0, k]) / delta
            deriv_y[-1, i, k] = (fct[-1, -1, k] - fct[-2, -1, k]) / delta

    for i in range(1, nx-1):
        for j in range(1, ny-1):
            deriv_y[0, j, k] = (fct[0, 1, k] - fct[0, 0, k]) / delta
            deriv_y[-1, j, k] = (fct[-1, -1, k] - fct[-1, -2, k]) / delta

    for i in range(1, nx-1):
        for j in range(1, ny-1):
            deriv_y[i, 0, k] = (fct[i+1, 0, k] - fct[i, 0, k]) / delta
            deriv_y[i, -1, k] = (fct[i, -1, k] - fct[i, -2, k]) / delta

    # z-direction boundaries
    for i in range(1, nx-1):
        for j in range(1, ny-1):
            deriv_z[i, j, 0] = (fct[i, j, 1] - fct[i, j, 0]) / delta
            deriv_z[i, j, -1] = (fct[i, j, -1] - fct[i, j, -2]) / delta

    return deriv_x, deriv_y, deriv_z
