def laplace(fct, delta):
    nx, ny, nz = fct.shape
    lap = zeros((nx, ny, nz))

    # Compute interior points using central differences
    for i in range(1, nx-1):
        for j in range(1, ny-1):
            for k in range(1, nz-1):
                lap[i, j, k] = (fct[i+1, j, k] + fct[i-1, j, k] + fct[i, j+1, k] + fct[i, j-1, k] + fct[i, j, k+1] + fct[i, j, k-1] - 6*fct[i, j, k]) / (delta**2)

    return lap
