import numpy as np

def SpeciesGrowth(g, pref, Rs, alive):
    N, R = g.shape
    g_temp = np.zeros(N)
    r_temp = np.zeros(N, dtype=int)

    for i in range(N):
        if alive[i]:
            for j in range(R):
                if pref[i, j] - 1 < R and Rs[pref[i, j] - 1] > 0:
                    g_temp[i] = g[i, pref[i, j] - 1]
                    r_temp[i] = pref[i, j]
                    break
            else:
                g_temp[i] = 0
        else:
            g_temp[i] = 0

    return g_temp, r_temp
